"""Report text realism separately from prediction errors; no selection or model fitting."""
import collections
import json
import re
from pathlib import Path
import pandas as pd

P=Path('output/v3-realism-vs-models')
def read(name):return json.loads((P/name).read_text())

def main():
    m=read('metrics.json');s=read('screen_summary.json');catalog=read('screen_catalog.json');manual=read('manual_review_with_predictions.json')
    lines=[]
    def add(*parts):
        for part in parts:lines.extend(part if isinstance(part,list) else [part])
    def table(headers,rows):return ['| '+' | '.join(headers)+' |','|'+'|'.join(['---']*len(headers))+'|']+['| '+' | '.join(str(v).replace('|','/').replace('\n',' ') for v in row)+' |' for row in rows]
    add('# V3: реалистичность и ошибки TF-IDF относительно C_syntax','',
        '**Короткий ответ:** на 48 вручную оценённых как обычные или сложные, но правдоподобные синтетических текстах TF-IDF ошибается в 25 случаях (52.1%). C_syntax полностью исправляет 15 из них: **31.25% всех 48 объявлений / 60% ошибок TF-IDF**. Есть 2 обратных случая, где TF-IDF верна, а C_syntax нет. Это случайная выборка из V3 test, не оценка частоты ошибок на реальном Авито.','',
        '**Крайне искусственные тексты остаются.** По историческому широкому текстовому критерию в текущем clean train 393/2921 кандидата (13.45%): 170 с четырьмя повторениями сложной рамки, 223 с тремя. В test 109/600 кандидатов (18.17%). В случайном просмотре 60 test-текстов экспертно искусственными названы 12 (20%). Это разные способы оценки; ни один не является установленной общей долей мусора в корпусе.','',
        'Модели не обучались, веса/пороги/датасеты/gold не изменялись. Использованы сохранённые результаты предыдущего fit TF-IDF и исходной C_syntax на одинаковом public3398 + V3 clean2921. Пороги обеих моделей 0.5, пространство 102–106, исходная категория исключается.','',
        '## 1. Что считалось ошибкой и исправлением','',
        'Ошибка объявления — хотя бы одна лишняя или пропущенная категория по синтетическому gold. Полное исправление — TF-IDF дала неверный набор, а C_syntax совпала с gold целиком. Поэтому частота ошибок объявлений — не 1−Micro-F1. В этой проверке не создавался новый официальный эталон.','',
        '## 2. Оценка реалистичности без отбора по ошибкам','',
        'Повторно применены прежние текстовые правила из `output/v3-realism-screen/screen.py`, существовавшие до этого сравнения. Они ищут повторяющиеся сложные рамки о владельце/бригаде, FAQ, исправлении прежнего отказа и платности; отдельно — фразу «отказ относится к бесплатной работе, а не к самой услуге» и старые SEO-теги. Признаки реалистичности не зависят от предсказания или его правильности.','',
        'Дополнительно до объединения с ответами моделей выбраны **60 равновероятных test-строк без возвращения**, numpy default_rng(42). Полные description показаны без колонок gold/prediction; для каждой сохранены категория реалистичности и обоснование. Оценки и критерии зафиксированы коммитом `b9ca7e8` до текущего объединения с предсказаниями. Корпус частично обсуждался ранее; это один экспертный просмотр в формате скрытых ответов, а не независимое двойное слепое исследование.','',
        '- **R — обычные:** понятное коммерческое предложение, обычные условия или единичный отказ; без учебного объяснения логики.',
        '- **P — сложные, но правдоподобные:** единичное уточнение о своей команде, старой услуге, FAQ или SEO; тяжеловесно, но ситуация возможна.',
        '- **A — искусственные:** повторение громоздкой логической рамки, объяснение смысла отрицания, серия одинаковых подтверждений или избыточный метатекст вместо объявления.',
        '', 'Сложное предложение не исключалось только из-за отрицания или того, что модель на нём ошибается. Ручная оценка реалистичности не доказывает корректность каждой gold-метки.','',
        '## 3. Насколько часто TF-IDF ошибается','')
    rows=[]
    for title,key in [('Все V3 test','all600'),('Без прежних сильных флагов и старых SEO-тегов','no_high_priority_flag'),('Кандидаты на переработку','rewrite_candidate'),('Только старые SEO-теги','stale_tag_only'),('Без крайних повторов/мета-логики','exclude_extreme')]:
        r=m['automatic'][key];rows.append([title,r['rows'],f"{r['tfidf_wrong_ads']} ({r['tfidf_wrong_pct']:.2f}%)",f"{r['c_syntax_wrong_ads']} ({r['c_syntax_wrong_pct']:.2f}%)",r['tfidf_wrong_c_syntax_exact_right'],f"{r['correction_pct_of_all']:.2f}%",r['tfidf_exact_right_c_syntax_wrong']])
    add(table(['Срез','N','TF-IDF ошиблась','C_syntax ошиблась','TF-IDF неверна → C_syntax верна','Доля всех объявлений','Обратные случаи'],rows),'',
        '**442 записи без флагов нельзя автоматически назвать реалистичными.** В ручной выборке найдены 2 искусственных текста даже без этих флагов и ещё 3 среди старых SEO-тегов. Автоматический срез — диагностический, а не проверенный эталон реалистичности. Ни одна строка физически не удалялась из test.','',
        'Ручная случайная выборка даёт более узкую, но содержательно проверенную оценку:','')
    add(table(['Экспертная группа','N','Ошибки TF-IDF','Ошибки C_syntax','Полностью исправлено C_syntax','Обратные случаи'],[
        [title,m['manual'][k]['rows'],f"{m['manual'][k]['tfidf_wrong_ads']} ({m['manual'][k]['tfidf_wrong_pct']:.2f}%)",f"{m['manual'][k]['c_syntax_wrong_ads']} ({m['manual'][k]['c_syntax_wrong_pct']:.2f}%)",f"{m['manual'][k]['tfidf_wrong_c_syntax_exact_right']} ({m['manual'][k]['correction_pct_of_all']:.2f}% всех)",m['manual'][k]['tfidf_exact_right_c_syntax_wrong']] for title,k in [('Обычные R','R'),('Правдоподобные сложные P','P'),('R + P','R_plus_P'),('Искусственные A','A')]]),'',
        'На R+P TF-IDF имеет 12 FP и 23 FN; C_syntax — 9 FP и 7 FN. Micro-F1 соответственно **0.751773 / 0.896104**. Проверка 15 полных исправлений по самим текстам не выявила явного переворота статуса услуги в gold; исходный mcId и отсутствие головы101 учтены как в исходном pipeline. Это экспертное чтение, не независимая переразметка.', '',
        'Выборка небольшая: 95% Wilson-интервал частоты ошибки TF-IDF на этих 48 R+P составляет '+str([round(100*v,1) for v in m['manual']['R_plus_P']['tfidf_error_rate_wilson95']])+'%. Он описывает неопределённость при выборочном подсчёте, без учёта ошибок оценки реалистичности и не переносится на реальный поток Авито. Строгая группа R содержит лишь17 записей; её проценты особенно нестабильны.','',
        'Искусственность не определяется ошибкой модели: в этой маленькой выборке на A TF-IDF ошиблась только в4 из12 случаев. В большом автоматическом срезе кандидатов ошибки79/109. Экспертные классы, автоматические флаги и фактическая трудность различаются; поэтому нельзя переобозначать все ошибки как «нереалистичные тексты».','',
        '## 4. Сколько в текущей V3 остаётся явно штампованных случаев','',
        'Текстовые счётчики по всей текущей версии, без использования ответов моделей:','')
    rows=[]
    for key,title in [('train','Clean train'),('validation','Validation'),('test','Test'),('challenge','Challenge'),('quarantine','Уже исключено из train')]:
        d=s[key];b=d['tiers'].get('rewrite_candidate',0)
        rows.append([title,d['rows'],f"{d['extreme_or_meta']} ({100*d['extreme_or_meta']/d['rows']:.2f}%)",d['at_least4_or_meta'],f"{b} ({100*b/d['rows']:.2f}%)",d['tiers'].get('review_stale_tag',0),d['tiers'].get('no_high_priority_flag',0)])
    add(table(['Часть','N','Крайний флаг: ≥5 повторов или мета-объяснение','≥4 повтора или мета','Широкий флаг: ≥3 повтора или мета','Только старые SEO','Без флагов'],rows),'',
        '**Не складывать столбцы:** крайние случаи входят в широкие кандидаты. SEO-столбец содержит только записи без широкого флага. Отсутствие флага не доказывает реалистичность; наличие флага не доказывает ошибку gold. Challenge144 — это только24 уникальных текста с разными исходными категориями, его не считаем144 независимыми примерами.','',
        'В повторённых формальных проверках found=offered−source, согласованности evidence-span и статусов одной категории структурных дефектов не найдено. Это не доказывает смысловую правильность всех меток. Искусственность языка и неверный gold — разные свойства; полный смысловой аудит всех 2921 train-строк здесь не выполнялся.','',
        'В основных clean train/validation/test вместе4121 строка; широких кандидатов595 (14.44%). Отдельные79 из quarantine не входят в текущий train. Ранее из него убрали только крайние случаи с5–6 повторами; **393 записи с3–4 повторами остались**. Из них170 с4 повторами — разумная первая очередь для содержательной переработки, остальные223 с3 требуют проверки. Этот аудит ничего не удалял и не разрешает автоматически выбросить все393: это изменит состав многометочных примеров и упростит корпус.','',
        'В test55 строк имеют ≥5 повторов либо прямое объяснение логики;43 текста содержат фразу об отказе только от бесплатности. По более широкому критерию всего109 кандидатов. Различные пороги показаны как чувствительность текстового скрининга, без выбора по качеству модели.','',
        f"По случайному просмотру искусственными выглядят **12/60=20%** test-объявлений. При условии фиксированных экспертных оценок грубый95% Wilson-интервал — [{100*m['artificial_sample']['wilson95'][0]:.1f}; {100*m['artificial_sample']['wilson95'][1]:.1f}]%. Это не утверждение, что ровно120 из600 плохие, и не оценка процента для train. Классификация одного аудитора спорна и не измеряет частоты на настоящем Авито.",'',
        '## 5. Реалистичные примеры, где TF-IDF ошиблась, а C_syntax верна','',
        'Тексты ниже из заранее размеченной R-группы. Примеры выбраны после подсчёта только для объяснения результата; частоты считаются по всему зафиксированному срезу. Полные description без сокращений:','')
    byrow={r['row_idx']:r for r in manual}
    for i in [52,364,459,467]:
        r=byrow[i];assert r['realism']=='R' and r['tfidf_error'] and not r['c_syntax_error']
        add('',f"### Test, строка {i}; mcId={r['source_mcId']}",'','```text',r['description'],'```','',
            f"Gold: `{r['gold']}`; TF-IDF: `{r['tfidf_prediction']}`; C_syntax: `{r['c_syntax_prediction']}`.")
    add('','Категории:102 штукатурка,103 плитка,104 сантехника,105 электрика,106 обои/малярка. Здесь видны и обычные пропуски положительных услуг, и ложное приписывание чужих работ. Выигрыш не ограничивается вложенными отрицаниями.','',
        '## 6. Обратные случаи в правдоподобной выборке','')
    for r in manual:
        if r['realism'] in ['R','P'] and not r['tfidf_error'] and r['c_syntax_error']:
            add('',f"### Test, строка {r['row_idx']}; группа {r['realism']}; mcId={r['source_mcId']}",'','```text',r['description'],'```','',
                f"Gold/TF-IDF: `{r['gold']}`; C_syntax: `{r['c_syntax_prediction']}`.")
    add('','C_syntax тоже ошибается: в525 добавляет сантехнику после прямого отказа, в478 теряет электрику и малярку, выполняемые собственной командой. Эти случаи оставлены в срезе и не переобозначались искусственными после просмотра ошибок.','',
        '## 7. Полный реестр 60 экспертных решений','')
    add(table(['Строка','Класс','Gold','TF-IDF','C_syntax','Обоснование реалистичности'],[[r['row_idx'],r['realism'],str(r['gold']),str(r['tfidf_prediction']),str(r['c_syntax_prediction']),r['rationale']] for r in manual]),'',
        '## 8. Артефакты и воспроизведение','',
        '`protocol.json`, `blind_sample_inputs.json`, `blind_annotations.json`, `blind_annotations_freeze.json` — зафиксированные критерии, все60 полных текстов и экспертные оценки. `manual_review_with_predictions.json` — последующее объединение с ответами. `screen_labels.csv` — построчный список всех частей с флагами без копирования исходных датасетов. `metrics.json` — все числа, `verification.json` — проверки.', '',
        'Из корня проекта: `python output/v3-realism-vs-models/prepare.py`, затем `analyze.py`, `build_report.py`, `verify.py` в той же папке. Использовался `/tmp/innopolis-qwen-emb-venv/bin/python`. prepare.py не читает предсказания, analyze.py не вызывает fit/predict. Ни одного нового обучения или изменения весов, порогов, данных и gold не выполнялось.')
    # Improve readability of narrative strings while preserving verbatim text blocks.
    for idx,line in enumerate(lines):
        if line.startswith(('**','В основных','Отдельные','В test','По случайному','Строгая','По более','Категории:','C_syntax тоже','`protocol')):
            for a,b in [('в525','в 525'),('в478','в 478'),('всего109','всего 109'),('вместе4121','вместе 4121'),('кандидатов595','кандидатов 595'),('Отдельные79','Отдельные 79'),('с5–6','с 5–6'),('с3–4','с 3–4'),('все393','все 393'),('из600','из 600'),('ровно120','ровно 120'),('всего60','всего 60'),('все60','все 60'),('Категории:102','Категории: 102'),(',103',', 103'),(',104',', 104'),(',105',', 105'),(',106',', 106')]:line=line.replace(a,b)
            lines[idx]=line
    # Clean narrative spacing without altering verbatim descriptions inside fences.
    in_fence=False
    for idx,line in enumerate(lines):
        if line.startswith('```'):
            in_fence=not in_fence
            continue
        if not in_fence:
            line=re.sub(r'([А-Яа-яЁё])(\d)',r'\1 \2',line)
            line=re.sub(r'(\d)([А-Яа-яЁё])',r'\1 \2',line)
            line=re.sub(r'\b(test|train|Challenge|public|clean)(\d)',r'\1 \2',line)
            line=re.sub(r';(?=\d)',r'; ',line)
            lines[idx]=line
    (P/'report.md').write_text('\n'.join(lines).rstrip()+'\n')
    flags=[]
    for split,rs in catalog.items():
        for r in rs:flags.append(dict(split=split,row_idx=r['row_idx'],item_id=r['item_id'],tier=r['tier'],max_complex_repeats=r['max_complex_repeats'],extreme_flag=r['extreme_flag'],reasons=';'.join(r['reasons'])))
    pd.DataFrame(flags).to_csv(P/'screen_labels.csv',index=False)
    print('Wrote report, 60-row review registry, and full split flag lists.')

if __name__=='__main__':main()
